@page "/settings"
@rendermode InteractiveServer
@using sv_febb54f428384f41b9e510d7278e5b6e.Models
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <!-- Sidebar Navigation -->
    <nav class="settings-sidebar">
        <h3 class="sidebar-title">Settings</h3>
        @foreach (var section in _sections)
        {
            <button class="sidebar-item @(ActiveSection == section.Key ? "active" : "")"
                    @onclick="() => SetActiveSection(section.Key)">
                <span class="sidebar-icon">@section.Value.Icon</span>
                <span>@section.Value.Label</span>
            </button>
        }
    </nav>

    <!-- Main Content Area -->
    <div class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            <!-- Toast Message -->
            @if (!string.IsNullOrEmpty(_toastMessage))
            {
                <div class="toast-message @(_toastIsError ? "toast-error" : "toast-success")">
                    @_toastMessage
                    <button class="toast-close" @onclick="DismissToast">✕</button>
                </div>
            }

            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }
    </div>
</div>

<!-- Revoke Session Confirmation Dialog -->
@if (_showRevokeConfirm)
{
    <div class="modal-backdrop" @onclick="CancelRevoke">
        <div class="confirm-dialog" @onclick:stopPropagation="true">
            <h4>Revoke Session</h4>
            <p>Are you sure you want to revoke the session on <strong>@_revokeSessionDevice</strong>? This will sign out that device immediately.</p>
            <div class="confirm-actions">
                <button class="btn btn-outline-secondary" @onclick="CancelRevoke">Cancel</button>
                <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke Session</button>
            </div>
        </div>
    </div>
}

@code {
    // ── Section definitions ──
    private readonly Dictionary<string, (string Label, string Icon)> _sections = new()
    {
        ["profile"] = ("Profile", "👤"),
        ["notifications"] = ("Notifications", "🔔"),
        ["security"] = ("Security", "🔒"),
        ["appearance"] = ("Appearance", "🎨"),
    };

    // ── State ──
    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;

    // Toast
    private string? _toastMessage;
    private bool _toastIsError;
    private CancellationTokenSource? _toastCts;

    // Profile
    private UserProfile? _savedProfile;
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";

    // Notifications
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _allChannels = [];
    private HashSet<string> _mutedChannels = [];

    // Security
    private SecuritySettings? _security;
    private bool _showChangePassword;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _showRevokeConfirm;
    private string? _revokeSessionId;
    private string? _revokeSessionDevice;

    // Appearance
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private static readonly string[] AvailableLanguages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese", "Korean"];

    // ── Lifecycle ──

    protected override async Task OnInitializedAsync()
    {
        await LoadAllData();
        _loading = false;
    }

    private async Task LoadAllData()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        ApplyProfile(await profileTask);
        ApplyNotificationPrefs(await notifTask);
        _security = await securityTask;
        ApplyAppearance(await appearanceTask);
    }

    // ── Navigation ──

    private void SetActiveSection(string section) => ActiveSection = section;

    // ── Toast Helpers ──

    private async Task ShowToast(string message, bool isError = false)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        _toastMessage = message;
        _toastIsError = isError;
        StateHasChanged();

        try
        {
            await Task.Delay(4000, _toastCts.Token);
            DismissToast();
        }
        catch (TaskCanceledException) { }
    }

    private void DismissToast()
    {
        _toastMessage = null;
        StateHasChanged();
    }

    // ═══════════════════════════════════════════
    //  PROFILE
    // ═══════════════════════════════════════════

    private void ApplyProfile(UserProfile profile)
    {
        _savedProfile = profile;
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
            ApplyProfile(_savedProfile);
    }

    private async Task SaveProfile()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!");
    }

    private RenderFragment RenderProfileSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Profile</h2>
            <p class="section-description">Manage your personal information and public profile.</p>

            <div class="form-group avatar-group">
                <label>Avatar</label>
                <div class="avatar-preview">
                    <img src="@_avatarUrl" alt="Avatar" class="avatar-img" />
                </div>
                <input type="text" class="form-control" value="@_avatarUrl"
                       @onchange="(e => _avatarUrl = e.Value?.ToString() ?? "")"
                       placeholder="Avatar URL" />
            </div>

            <div class="form-group">
                <label>Display Name</label>
                <input type="text" class="form-control"
                       @bind="_displayName" @bind:event="oninput" />
            </div>

            <div class="form-group">
                <label>Email</label>
                <input type="email" class="form-control"
                       @bind="_email" @bind:event="oninput" />
            </div>

            <div class="form-group">
                <label>Bio</label>
                <textarea class="form-control" rows="4"
                          @bind="_bio" @bind:event="oninput"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };

    // ═══════════════════════════════════════════
    //  NOTIFICATIONS
    // ═══════════════════════════════════════════

    private void ApplyNotificationPrefs(NotificationPrefs prefs)
    {
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _allChannels = new List<string>(prefs.MutedChannels);
        _mutedChannels = new HashSet<string>(prefs.MutedChannels);
    }

    private void ToggleChannelMute(string channel)
    {
        if (!_mutedChannels.Remove(channel))
            _mutedChannels.Add(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(
            _emailNotifications,
            _pushNotifications,
            _weeklyDigest,
            _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved!");
    }

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Notifications</h2>
            <p class="section-description">Control how and when you receive notifications.</p>

            <div class="toggle-group">
                <div class="toggle-row">
                    <div>
                        <strong>Email Notifications</strong>
                        <p class="toggle-description">Receive notifications via email</p>
                    </div>
                    <label class="switch">
                        <input type="checkbox" @bind="_emailNotifications" />
                        <span class="slider"></span>
                    </label>
                </div>

                <div class="toggle-row">
                    <div>
                        <strong>Push Notifications</strong>
                        <p class="toggle-description">Receive push notifications on your devices</p>
                    </div>
                    <label class="switch">
                        <input type="checkbox" @bind="_pushNotifications" />
                        <span class="slider"></span>
                    </label>
                </div>

                <div class="toggle-row">
                    <div>
                        <strong>Weekly Digest</strong>
                        <p class="toggle-description">Get a summary of activity every week</p>
                    </div>
                    <label class="switch">
                        <input type="checkbox" @bind="_weeklyDigest" />
                        <span class="slider"></span>
                    </label>
                </div>
            </div>

            <h4 class="subsection-title">Muted Channels</h4>
            <p class="section-description">Uncheck channels to unmute them and start receiving notifications.</p>
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox" checked="@_mutedChannels.Contains(channel)"
                               @onchange="() => ToggleChannelMute(channel)" />
                        <span class="channel-name">#@channel</span>
                        <span class="channel-badge @(!_mutedChannels.Contains(channel) ? "unmuted" : "")">
                            @(_mutedChannels.Contains(channel) ? "Muted" : "Active")
                        </span>
                    </label>
                }
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>
    };

    // ═══════════════════════════════════════════
    //  SECURITY
    // ═══════════════════════════════════════════

    private void ToggleChangePassword() => _showChangePassword = !_showChangePassword;

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            await ShowToast("Please enter your current password.", true);
            return;
        }
        if (_newPassword.Length < 8)
        {
            await ShowToast("New password must be at least 8 characters.", true);
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            await ShowToast("Passwords do not match.", true);
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _security = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _showChangePassword = false;
        await ShowToast("Password updated successfully!");
    }

    private void RequestRevoke(string sessionId, string device)
    {
        _revokeSessionId = sessionId;
        _revokeSessionDevice = device;
        _showRevokeConfirm = true;
    }

    private void CancelRevoke() => _showRevokeConfirm = false;

    private async Task ConfirmRevoke()
    {
        if (_revokeSessionId is not null)
        {
            await SettingsService.RevokeSessionAsync(_revokeSessionId);
            _security = await SettingsService.GetSecuritySettingsAsync();
        }
        _showRevokeConfirm = false;
        await ShowToast("Session revoked.");
    }

    private async Task ToggleTwoFactor()
    {
        if (_security is null) return;
        _security = _security with { TwoFactorEnabled = !_security.TwoFactorEnabled };
        await ShowToast(_security.TwoFactorEnabled
            ? "Two-factor authentication enabled."
            : "Two-factor authentication disabled.");
    }

    private static string FormatTimeAgo(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <section class="settings-section">
            <h2>Security</h2>
            <p class="section-description">Manage your password, two-factor authentication, and active sessions.</p>

            <!-- Change Password -->
            <div class="expandable-panel">
                <button class="panel-header" @onclick="ToggleChangePassword">
                    <span>🔑 Change Password</span>
                    <span class="expand-icon">@(_showChangePassword ? "▲" : "▼")</span>
                </button>
                @if (_showChangePassword)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label>Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label>New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label>Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>

                        @if (_security?.LastPasswordChange is not null)
                        {
                            <p class="hint-text">Last changed: @_security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                        }
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="toggle-group" style="margin-top: 1.5rem;">
                <div class="toggle-row">
                    <div>
                        <strong>Two-Factor Authentication</strong>
                        <p class="toggle-description">
                            Add an extra layer of security to your account.
                            <span class="status-badge @(_security?.TwoFactorEnabled == true ? "status-on" : "status-off")">
                                @(_security?.TwoFactorEnabled == true ? "Enabled" : "Disabled")
                            </span>
                        </p>
                    </div>
                    <label class="switch">
                        <input type="checkbox" checked="@(_security?.TwoFactorEnabled ?? false)"
                               @onchange="async () => await ToggleTwoFactor()" />
                        <span class="slider"></span>
                    </label>
                </div>
            </div>

            <!-- Active Sessions -->
            <h4 class="subsection-title" style="margin-top: 2rem;">Active Sessions</h4>
            @if (_security?.Sessions is { Count: > 0 })
            {
                <div class="sessions-table-wrapper">
                    <table class="table sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var (session, index) in _security.Sessions.Select((s, i) => (s, i)))
                            {
                                <tr>
                                    <td>
                                        @session.Device
                                        @if (index == 0)
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                    <td>@session.Location</td>
                                    <td>@FormatTimeAgo(session.LastActive)</td>
                                    <td>
                                        @if (index != 0)
                                        {
                                            <button class="btn btn-sm btn-outline-danger"
                                                    @onclick="() => RequestRevoke(session.Id, session.Device)">
                                                Revoke
                                            </button>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
        </section>
    };

    // ═══════════════════════════════════════════
    //  APPEARANCE
    // ═══════════════════════════════════════════

    private void ApplyAppearance(AppearanceSettings settings)
    {
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved!");
    }

    private string PreviewFontSize => _fontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem"
    };

    private string PreviewBackground => _theme switch
    {
        "Dark" => "#1e1e2e",
        _ => "#ffffff"
    };

    private string PreviewText => _theme switch
    {
        "Dark" => "#cdd6f4",
        _ => "#1a1a2e"
    };

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Appearance</h2>
            <p class="section-description">Customize the look and feel of the application.</p>

            <!-- Theme Selector -->
            <div class="form-group">
                <label class="group-label">Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-card @(_theme == theme ? "selected" : "")">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <span class="radio-card-icon">
                                @(theme switch { "Light" => "☀️", "Dark" => "🌙", _ => "💻" })
                            </span>
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Font Size Selector -->
            <div class="form-group">
                <label class="group-label">Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-card @(_fontSize == size ? "selected" : "")">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <span class="radio-card-icon" style="font-size: @(size switch { "Small" => "0.9rem", "Large" => "1.4rem", _ => "1.1rem" })">
                                Aa
                            </span>
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Language Dropdown -->
            <div class="form-group">
                <label class="group-label">Language</label>
                <select class="form-control" @bind="_language">
                    @foreach (var lang in AvailableLanguages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="toggle-group">
                <div class="toggle-row">
                    <div>
                        <strong>Compact Mode</strong>
                        <p class="toggle-description">Reduce spacing and padding for a denser layout</p>
                    </div>
                    <label class="switch">
                        <input type="checkbox" @bind="_compactMode" />
                        <span class="slider"></span>
                    </label>
                </div>
            </div>

            <!-- Live Preview -->
            <h4 class="subsection-title" style="margin-top: 1.5rem;">Preview</h4>
            <div class="appearance-preview"
                 style="background: @PreviewBackground; color: @PreviewText; font-size: @PreviewFontSize; padding: @(_compactMode ? "0.75rem" : "1.25rem");">
                <div class="preview-header" style="border-bottom: 1px solid @(_theme == "Dark" ? "#45475a" : "#e0e0e0"); padding-bottom: @(_compactMode ? "0.4rem" : "0.75rem"); margin-bottom: @(_compactMode ? "0.4rem" : "0.75rem");">
                    <strong>Dashboard</strong>
                    <span style="opacity: 0.6; margin-left: 1rem;">Home &gt; Settings &gt; Appearance</span>
                </div>
                <p style="margin: @(_compactMode ? "0.25rem 0" : "0.5rem 0");">Welcome back, <strong>@_displayName</strong>! Here's how your content will look.</p>
                <p style="margin: @(_compactMode ? "0.25rem 0" : "0.5rem 0"); opacity: 0.7;">
                    Theme: @_theme · Font: @_fontSize · Language: @_language · Compact: @(_compactMode ? "On" : "Off")
                </p>
                <div style="display: flex; gap: 0.5rem; margin-top: @(_compactMode ? "0.5rem" : "0.75rem");">
                    <span style="background: @(_theme == "Dark" ? "#89b4fa" : "#3b82f6"); color: white; padding: 0.25rem 0.75rem; border-radius: 4px;">Primary</span>
                    <span style="background: @(_theme == "Dark" ? "#45475a" : "#e5e7eb"); padding: 0.25rem 0.75rem; border-radius: 4px;">Secondary</span>
                </div>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };
}

/* ═══════════════════════════════════════
   Settings Layout
   ═══════════════════════════════════════ */

.settings-layout {
    display: flex;
    min-height: calc(100vh - 6rem);
    gap: 0;
    margin: -1rem -1.5rem;
}

/* ── Sidebar ── */

.settings-sidebar {
    width: 240px;
    min-width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e9ecef;
    padding: 1.5rem 0;
    display: flex;
    flex-direction: column;
}

.sidebar-title {
    font-size: 0.85rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #6c757d;
    padding: 0 1.25rem;
    margin-bottom: 0.75rem;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.7rem 1.25rem;
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    cursor: pointer;
    font-size: 0.95rem;
    color: #495057;
    transition: all 0.15s ease;
}

.sidebar-item:hover {
    background: #e9ecef;
    color: #212529;
}

.sidebar-item.active {
    background: #e7f1ff;
    color: #0d6efd;
    font-weight: 600;
    border-right: 3px solid #0d6efd;
}

.sidebar-icon {
    font-size: 1.2rem;
    width: 1.5rem;
    text-align: center;
}

/* ── Content Area ── */

.settings-content {
    flex: 1;
    padding: 2rem 2.5rem;
    max-width: 800px;
    position: relative;
}

.settings-section h2 {
    font-size: 1.5rem;
    font-weight: 700;
    margin-bottom: 0.25rem;
    color: #1a1a2e;
}

.section-description {
    color: #6c757d;
    margin-bottom: 1.5rem;
    font-size: 0.9rem;
}

.subsection-title {
    font-size: 1.05rem;
    font-weight: 600;
    color: #343a40;
    margin-bottom: 0.75rem;
}

/* ── Loading ── */

.loading-spinner {
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 300px;
}

/* ── Toast ── */

.toast-message {
    position: fixed;
    top: 1.5rem;
    right: 1.5rem;
    z-index: 1100;
    padding: 0.75rem 1.25rem;
    border-radius: 8px;
    font-weight: 500;
    font-size: 0.9rem;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);
    animation: slideIn 0.3s ease;
}

.toast-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.toast-error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

.toast-close {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    opacity: 0.6;
    padding: 0;
    line-height: 1;
}

.toast-close:hover {
    opacity: 1;
}

@@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateY(-1rem);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* ═══════════════════════════════════════
   Form Elements
   ═══════════════════════════════════════ */

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label,
.group-label {
    display: block;
    font-weight: 600;
    font-size: 0.875rem;
    color: #495057;
    margin-bottom: 0.4rem;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 6px;
    font-size: 0.9rem;
    transition: border-color 0.15s ease;
}

.form-control:focus {
    border-color: #86b7fe;
    outline: none;
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.15);
}

textarea.form-control {
    resize: vertical;
}

select.form-control {
    max-width: 280px;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #e9ecef;
}

.hint-text {
    font-size: 0.8rem;
    color: #6c757d;
    margin-top: 0.75rem;
}

/* ═══════════════════════════════════════
   Avatar
   ═══════════════════════════════════════ */

.avatar-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.avatar-preview {
    width: 96px;
    height: 96px;
    border-radius: 50%;
    overflow: hidden;
    border: 3px solid #e9ecef;
}

.avatar-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

/* ═══════════════════════════════════════
   Toggle Switch
   ═══════════════════════════════════════ */

.toggle-group {
    background: #f8f9fa;
    border: 1px solid #e9ecef;
    border-radius: 8px;
    overflow: hidden;
}

.toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 1.25rem;
}

.toggle-row + .toggle-row {
    border-top: 1px solid #e9ecef;
}

.toggle-description {
    font-size: 0.8rem;
    color: #6c757d;
    margin: 0.15rem 0 0 0;
}

.switch {
    position: relative;
    display: inline-block;
    width: 48px;
    height: 26px;
    flex-shrink: 0;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background: #ccc;
    border-radius: 26px;
    transition: 0.2s;
}

.slider::before {
    content: "";
    position: absolute;
    height: 20px;
    width: 20px;
    left: 3px;
    bottom: 3px;
    background: white;
    border-radius: 50%;
    transition: 0.2s;
}

.switch input:checked + .slider {
    background: #0d6efd;
}

.switch input:checked + .slider::before {
    transform: translateX(22px);
}

/* ═══════════════════════════════════════
   Channels List
   ═══════════════════════════════════════ */

.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0;
    border: 1px solid #e9ecef;
    border-radius: 8px;
    overflow: hidden;
}

.channel-item {
