.channel-badge {
    font-size: 0.7rem;
    font-weight: 600;
    text-transform: uppercase;
    padding: 0.15rem 0.5rem;
    border-radius: 10px;
    background: #fce4ec;
    color: #c62828;
}

.channel-badge.unmuted {
    background: #e8f5e9;
    color: #2e7d32;
}

/* ═══════════════════════════════════════
