/* ═══════════════════════════════════════
   Settings Layout
   ═══════════════════════════════════════ */

.settings-layout {
    display: flex;
    min-height: calc(100vh - 6rem);
    gap: 0;
    margin: -1rem -1.5rem;
}

/* ── Sidebar ── */

.settings-sidebar {
    width: 240px;
    min-width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e9ecef;
    padding: 1.5rem 0;
    display: flex;
    flex-direction: column;
}

.sidebar-title {
    font-size: 0.85rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #6c757d;
    padding: 0 1.25rem;
    margin-bottom: 0.75rem;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.7rem 1.25rem;
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    cursor: pointer;
    font-size: 0.95rem;
    color: #495057;
    transition: all 0.15s ease;
}

.sidebar-item:hover {
    background: #e9ecef;
    color: #212529;
}

.sidebar-item.active {
    background: #e7f1ff;
    color: #0d6efd;
    font-weight: 600;
    border-right: 3px solid #0d6efd;
}

.sidebar-icon {
    font-size: 1.2rem;
    width: 1.5rem;
    text-align: center;
}

/* ── Content Area ── */

.settings-content {
    flex: 1;
    padding: 2rem 2.5rem;
    max-width: 800px;
    position: relative;
}

.settings-section h2 {
    font-size: 1.5rem;
    font-weight: 700;
    margin-bottom: 0.25rem;
    color: #1a1a2e;
}

.section-description {
    color: #6c757d;
    margin-bottom: 1.5rem;
    font-size: 0.9rem;
}

.subsection-title {
    font-size: 1.05rem;
    font-weight: 600;
    color: #343a40;
    margin-bottom: 0.75rem;
}

/* ── Loading ── */

.loading-spinner {
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 300px;
}

/* ── Toast ── */

.toast-message {
    position: fixed;
    top: 1.5rem;
    right: 1.5rem;
    z-index: 1100;
    padding: 0.75rem 1.25rem;
    border-radius: 8px;
    font-weight: 500;
    font-size: 0.9rem;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);
    animation: slideIn 0.3s ease;
}

.toast-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.toast-error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

.toast-close {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    opacity: 0.6;
    padding: 0;
    line-height: 1;
}

.toast-close:hover {
    opacity: 1;
}

@@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateY(-1rem);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* ═══════════════════════════════════════
   Form Elements
   ═══════════════════════════════════════ */

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label,
.group-label {
    display: block;
    font-weight: 600;
    font-size: 0.875rem;
    color: #495057;
    margin-bottom: 0.4rem;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 6px;
    font-size: 0.9rem;
    transition: border-color 0.15s ease;
}

.form-control:focus {
    border-color: #86b7fe;
    outline: none;
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.15);
}

textarea.form-control {
    resize: vertical;
}

select.form-control {
    max-width: 280px;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #e9ecef;
}

.hint-text {
    font-size: 0.8rem;
    color: #6c757d;
    margin-top: 0.75rem;
}

/* ═══════════════════════════════════════
   Avatar
   ═══════════════════════════════════════ */

.avatar-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.avatar-preview {
    width: 96px;
    height: 96px;
    border-radius: 50%;
    overflow: hidden;
    border: 3px solid #e9ecef;
}

.avatar-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

/* ═══════════════════════════════════════
   Toggle Switch
   ═══════════════════════════════════════ */

.toggle-group {
    background: #f8f9fa;
    border: 1px solid #e9ecef;
    border-radius: 8px;
    overflow: hidden;
}

.toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 1.25rem;
}

.toggle-row + .toggle-row {
    border-top: 1px solid #e9ecef;
}

.toggle-description {
    font-size: 0.8rem;
    color: #6c757d;
    margin: 0.15rem 0 0 0;
}

.switch {
    position: relative;
    display: inline-block;
    width: 48px;
    height: 26px;
    flex-shrink: 0;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background: #ccc;
    border-radius: 26px;
    transition: 0.2s;
}

.slider::before {
    content: "";
    position: absolute;
    height: 20px;
    width: 20px;
    left: 3px;
    bottom: 3px;
    background: white;
    border-radius: 50%;
    transition: 0.2s;
}

.switch input:checked + .slider {
    background: #0d6efd;
}

.switch input:checked + .slider::before {
    transform: translateX(22px);
}

/* ═══════════════════════════════════════
   Channels List
   ═══════════════════════════════════════ */

.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0;
    border: 1px solid #e9ecef;
    border-radius: 8px;
    overflow: hidden;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.65rem 1rem;
    cursor: pointer;
    margin: 0;
    transition: background 0.1s;
}

.channel-item:hover {
    background: #f8f9fa;
}

.channel-item + .channel-item {
    border-top: 1px solid #e9ecef;
}

.channel-item input[type="checkbox"] {
    width: 16px;
    height: 16px;
    accent-color: #0d6efd;
}

.channel-name {
    flex: 1;
    font-family: monospace;
    font-size: 0.9rem;
}

.channel-badge {
    font-size: 0.7rem;
    font-weight: 600;
    text-transform: uppercase;
    padding: 0.15rem 0.5rem;
    border-radius: 10px;
    background: #fce4ec;
    color: #c62828;
}

.channel-badge.unmuted {
    background: #e8f5e9;
    color: #2e7d32;
}

/* ═══════════════════════════════════════
   Expandable Panel
   ═══════════════════════════════════════ */

.expandable-panel {
    border: 1px solid #e9ecef;
    border-radius: 8px;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 1.25rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 600;
    color: #343a40;
    transition: background 0.15s;
}

.panel-header:hover {
    background: #e9ecef;
}

.expand-icon {
    font-size: 0.75rem;
    color: #6c757d;
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid #e9ecef;
}

/* ═══════════════════════════════════════
   Status Badge
   ═══════════════════════════════════════ */

.status-badge {
    display: inline-block;
    font-size: 0.7rem;
    font-weight: 700;
    text-transform: uppercase;
    padding: 0.15rem 0.5rem;
    border-radius: 10px;
